#include <stdio.h>
#include <stdlib.h>

#define SIZE 10

typedef struct {
    int key;
    int val;
    int occupied;
} Entry;

// دالة تجزئة بسيطة: باقي القسمة على الحجم
int hash(int key) { return key % SIZE; }

void insert(Entry *table, int key, int val) {
    int idx = hash(key);
    // تطوير خطي: نبحث عن خلية فارغة
    while (table[idx].occupied) {
        idx = (idx + 1) % SIZE;
    }
    table[idx].key = key;
    table[idx].val = val;
    table[idx].occupied = 1;
}

int get(Entry *table, int key) {
    int idx = hash(key);
    while (table[idx].occupied) {
        if (table[idx].key == key) return table[idx].val;
        idx = (idx + 1) % SIZE;
    }
    return -1;
}

int main(void) {
    Entry table[SIZE] = {0};
    insert(table, 5, 50);
    insert(table, 15, 150); // يتصادم مع 5 ثم ينتقل للخلية التالية
    insert(table, 25, 250);

    printf("%d ", get(table, 5));
    printf("%d ", get(table, 15));
    printf("%d\n", get(table, 25));
    return 0;
}

