    // بناء المثلث: كل عنصر يساوي مجموع العنصرين فوقه
    for (int i = 0; i < rows; i++) {
        triangle[i][0] = triangle[i][i] = 1;
        for (int j = 1; j < i; j++) {
            triangle[i][j] = triangle[i-1][j-1] + triangle[i-1][j];
