}

#include <stdio.h>

int isPerfect(int n) {
    int sum = 1; // 1 دائمًا قاسم صحيح
    for (int i = 2; i * i <= n; i++) {
        if (n % i == 0) {
            sum += i;
            if (i != n / i) sum += n / i;
        }
    }
    return (n > 1) && (sum == n);
}

int main(void) {
    int limit = 500;
    printf("Perfect numbers up to %d:\n", limit);
    for (int i = 2; i <= limit; i++) {
        if (isPerfect(i)) printf("%d\n", i);
    }
    return 0;
}

