typedef struct Node {
    int data;
    struct Node *next;
} Node;

// إضافة عقدة في المقدمة: نربط العقدة الجديدة بالرأس القديم ثم نحدّث الرأس
void push(Node **head, int val) {
    Node *newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return;
    newNode->data = val;
    newNode->next = *head;
    *head = newNode;
}

int main(void) {
    Node *head = NULL;
    push(&head, 3);
    push(&head, 2);
    push(&head, 1);

    for (Node *cur = head; cur != NULL; cur = cur->next) {
        printf("%d -> ", cur->data);
    }
    printf("NULL\n");

    // تحرير الذاكرة
    while (head) {
        Node *tmp = head;
        head = head->next;
        free(tmp);
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

#define MAX 5

typedef struct {
    int arr[MAX];
    int top;
} Stack;

void init(Stack *s) { s->top = -1; }

int isFull(Stack *s) { return s->top == MAX - 1; }
int isEmpty(Stack *s) { return s->top == -1; }

void push(Stack *s, int val) {
    if (isFull(s)) return;
    s->arr[++s->top] = val;
}

int pop(Stack *s) {
    if (isEmpty(s)) return -1;
    return s->arr[s->top--];
}

int peek(Stack *s) {
    if (isEmpty(s)) return -1;
    return s->arr[s->top];
}

int main(void) {
    Stack s;
    init(&s);
    push(&s, 10);
    push(&s, 20);
    push(&s, 30);

    printf("Top: %d\n", peek(&s));
    printf("Pop: %d\n", pop(&s));
    printf("Pop: %d\n", pop(&s));
    printf("Empty? %d\n", isEmpty(&s));
    return 0;
}

