void trim(char* s) {
    int start = 0, end = strlen(s) - 1;
    while (isspace(s[start])) start++;
    while (end >= start && isspace(s[end])) end--;
    int i;
    for (i = 0; start <= end; i++, start++) {
        s[i] = s[start];
    }
    s[i] = '\0';
}

int main(void) {
    char text[] = "   hello world   ";
    trim(text);
    printf("[%s]\n", text);
    return 0;
}

